INSERT OR REPLACE INTO indicators (code, name, category, definition, rubric_json, sort_order) VALUES ('OBJ', '保护对象覆盖度', '保护体系', '法规是否形成从名城整体到街区、建筑、环境要素与非物质文化遗产的分层保护对象体系。', '["未列明保护对象","仅规定名城或少数对象","覆盖多类物质遗产","形成物质与非物质遗产的完整分层体系"]', 1);
INSERT OR REPLACE INTO indicators (code, name, category, definition, rubric_json, sort_order) VALUES ('BND', '保护范围与保护边界', '保护体系', '是否明确保护范围、核心区与建设控制地带，并规定边界公布、标识和调整程序。', '["无范围规定","笼统提及保护范围","要求划定范围或控制地带","边界、图则、公布和调整程序均明确"]', 2);
INSERT OR REPLACE INTO indicators (code, name, category, definition, rubric_json, sort_order) VALUES ('RESP', '责任主体明确度', '治理机制', '政府、主管部门、产权人、使用人及其他主体的职责是否具体且可归责。', '["无明确主体","仅笼统规定政府负责","明确主管部门及部分主体","多主体职责、权限和履责要求完整"]', 3);
INSERT OR REPLACE INTO indicators (code, name, category, definition, rubric_json, sort_order) VALUES ('COORD', '部门协同机制', '治理机制', '是否建立跨部门议事协调、信息共享、联合执法或争议处理机制。', '["无协同规定","原则性要求配合","明确牵头与协作部门","具备常态化议事、共享或联合执法机制"]', 4);
INSERT OR REPLACE INTO indicators (code, name, category, definition, rubric_json, sort_order) VALUES ('PLAN', '保护规划制度', '规划管控', '保护规划的编制、审批、衔接、公开、实施评估与修改程序是否完整。', '["无规划制度","仅要求编制规划","规定编制与审批程序","覆盖公开、实施、评估和修改全周期"]', 5);
INSERT OR REPLACE INTO indicators (code, name, category, definition, rubric_json, sort_order) VALUES ('PRE', '预先保护制度', '规划管控', '对尚未完成认定但具有保护价值的对象，是否可以先行登记、公告并采取临时措施。', '["无预先保护","仅有原则性保护表述","规定候选对象或临时措施","触发、期限、措施、解除及补偿机制完整"]', 6);
INSERT OR REPLACE INTO indicators (code, name, category, definition, rubric_json, sort_order) VALUES ('REPAIR', '修缮审批程序', '实施管理', '修缮、改建、迁移、拆除等活动是否具有分级分类审批及技术审查程序。', '["无审批规定","原则性要求批准","明确申请与审批机关","分类程序、材料、技术审查和监督验收完整"]', 7);
INSERT OR REPLACE INTO indicators (code, name, category, definition, rubric_json, sort_order) VALUES ('FUND', '资金来源', '保障激励', '财政投入、专项资金、社会资本、捐赠及资金监管安排是否多元和稳定。', '["无资金规定","仅原则性财政保障","明确专项资金或多元来源","来源稳定且预算、使用、监督机制完整"]', 8);
INSERT OR REPLACE INTO indicators (code, name, category, definition, rubric_json, sort_order) VALUES ('COMP', '征收补偿与利益激励', '保障激励', '征收补偿、产权置换、税费优惠、容积率转移、修缮补助等利益平衡工具是否充分。', '["无补偿激励","仅援引一般补偿","规定补助或优惠工具","形成多元补偿、激励与救济机制"]', 9);
INSERT OR REPLACE INTO indicators (code, name, category, definition, rubric_json, sort_order) VALUES ('RES', '原住民参与', '公众权益', '原住居民是否参与规划、更新、经营和监督，居住权与社区延续是否获得保障。', '["无居民参与","原则性听取意见","规定参与程序或权益保障","参与、反馈、社区延续和利益分享完整"]', 10);
INSERT OR REPLACE INTO indicators (code, name, category, definition, rubric_json, sort_order) VALUES ('BIZ', '商业业态准入', '实施管理', '历史街区内业态是否设置准入、负面清单、规模控制和动态退出规则。', '["无业态规则","原则性引导","规定限制或鼓励类型","准入清单、规模控制、评估退出机制完整"]', 11);
INSERT OR REPLACE INTO indicators (code, name, category, definition, rubric_json, sort_order) VALUES ('DIG', '数字化建档与监测', '技术支撑', '是否建立数字档案、数据库、动态监测、风险预警及数据更新制度。', '["无数字化规定","仅要求建立档案","明确数字建档或动态监测","数据库、监测、预警、共享和更新完整"]', 12);
INSERT OR REPLACE INTO indicators (code, name, category, definition, rubric_json, sort_order) VALUES ('SUP', '社会监督', '公众权益', '信息公开、举报投诉、公众监督、专家咨询和回应机制是否明确。', '["无监督渠道","原则性鼓励监督","明确公开或举报渠道","公开、举报、处理反馈和专家监督完整"]', 13);
INSERT OR REPLACE INTO indicators (code, name, category, definition, rubric_json, sort_order) VALUES ('LIAB', '法律责任和处罚强度', '责任追究', '违法行为、责任主体、处罚种类、罚款幅度、修复责任及公职人员责任是否匹配。', '["无专门责任","主要援引上位法","规定具体违法行为和处罚","处罚覆盖完整、幅度明确并含修复与履职责任"]', 14);
